+const canvas = document.querySelector<HTMLCanvasElement>('#render-canvas')!;
+const ctx = canvas.getContext('2d')!;
+const preview = document.querySelector<HTMLImageElement>('#preview')!;
+const quality = document.querySelector<HTMLSelectElement>('#quality')!;
+const resolution = document.querySelector<HTMLSelectElement>('#resolution')!;
+const mirror = document.querySelector<HTMLInputElement>('#mirror-color')!;
+const glass = document.querySelector<HTMLInputElement>('#glass-color')!;
+const stop = document.querySelector<HTMLButtonElement>('#stop')!;
+const errorBox = document.querySelector<HTMLDivElement>('#canvas-error')!;
+const progressTrack = document.querySelector<HTMLElement>('.progress-track')!;
+const base = import.meta.env.BASE_URL;
+let worker: Worker | undefined;
+let hasPixels = false;
+const text = (id: string, value: string) => { document.getElementById(id)!.textContent = value; };
+const rgb = (hex: string) => [1, 3, 5].map(i => Math.min(.999, parseInt(hex.slice(i, i + 2), 16) / 255));
+function swatches() {
+  text('mirror-hex', mirror.value.toUpperCase());
+  text('glass-hex', glass.value.toUpperCase());
+}
+function finish(label: string) {
+  stop.hidden = true;
+  text('progress-label', label);
+  document.getElementById('render-dot')!.classList.remove('pulsing');
+  worker?.terminate(); worker = undefined;
+}
+function showError(message: string) {
+  finish('Rendering failed. Try rendering the scene again.');
+  text('render-state', 'RENDER ERROR');
+  errorBox.textContent = `Unable to render: ${message}`;
+  errorBox.hidden = false;
+}
+function run() {
+  worker?.terminate();
+  if (hasPixels) preview.src = canvas.toDataURL('image/png');
+  preview.style.display = 'block';
+  hasPixels = false;
+  errorBox.hidden = true;
+  const width = Number(resolution.value), height = width * .75;
+  canvas.width = width; canvas.height = height;
+  text('resolution-readout', `${width} × ${height}`);
+  text('sample-readout', quality.value);
+  text('time-readout', '0.0 s');
+  text('render-state', 'RENDERING');
+  text('progress-label', 'Tracing light, one ray at a time…');
+  text('progress-percent', '0%');
+  document.getElementById('progress-fill')!.style.width = '0%';
+  progressTrack.setAttribute('aria-valuenow', '0');
+  document.getElementById('render-dot')!.classList.add('pulsing');
+  stop.hidden = false;
+  try {
+    worker = new Worker(`${base}smallpt/worker.js`, { type: 'module' });
+    worker.onerror = (event) => showError(event.message || 'WebAssembly could not be loaded.');
+    worker.onmessage = ({ data }) => {
+      if (data.type === 'error') return showError(data.message);
+      if (data.type === 'progress') {
+        hasPixels = true;
+        ctx.putImageData(new ImageData(new Uint8ClampedArray(data.pixels), width, data.rows), 0, data.row);
+        const percent = Math.round(data.progress * 100);
+        text('progress-percent', `${percent}%`);
+        text('time-readout', `${data.elapsed.toFixed(1)} s`);
+        document.getElementById('progress-fill')!.style.width = `${percent}%`;
+        progressTrack.setAttribute('aria-valuenow', String(percent));
+      }
+      if (data.type === 'done') {
+        preview.style.display = 'none';
+        text('render-state', 'RENDER COMPLETE');
+        finish(`All done. ${Number(quality.value).toLocaleString()} samples per pixel. A little light, well travelled.`);
+      }
+    };
+    worker.postMessage({ width, height, samples: Number(quality.value), seed: crypto.getRandomValues(new Uint32Array(1))[0], colors: [rgb(mirror.value), rgb(glass.value)] });
+  } catch (error) { showError(error instanceof Error ? error.message : String(error)); }
+}
+const palettes = ['#b8ebd3', '#f2af91', '#d1b6ef', '#edcf8c', '#9ccde8', '#e8a6bd', '#bbd99e', '#b9d9db'];
+document.getElementById('randomize')!.addEventListener('click', () => {
+  const choices = palettes.filter(c => c !== mirror.value);
+  mirror.value = choices[crypto.getRandomValues(new Uint32Array(1))[0] % choices.length];
+  const others = palettes.filter(c => c !== mirror.value && c !== glass.value);
+  glass.value = others[crypto.getRandomValues(new Uint32Array(1))[0] % others.length];
+  swatches(); run();
+});
+document.getElementById('render')!.addEventListener('click', run);
+document.getElementById('reset')!.addEventListener('click', () => {
+  mirror.value = '#ffffff'; glass.value = '#ffffff'; quality.value = '64'; resolution.value = '480'; swatches(); run();
+});
+mirror.addEventListener('input', swatches); glass.addEventListener('input', swatches);
+stop.addEventListener('click', () => { finish('Rendering stopped. Change the scene or render again.'); text('render-state', 'RENDER STOPPED'); });
+document.getElementById('download')!.addEventListener('click', () => {
+  const link = document.createElement('a');
+  link.download = 'smallpt-render.png';
+  link.href = hasPixels ? canvas.toDataURL('image/png') : `${base}smallpt/preview.png`;
+  link.click();
+});
+window.addEventListener('pagehide', () => worker?.terminate());
+// Keep a real, pre-rendered smallpt image visible while the WASM module loads.
+if ('WebAssembly' in window && 'Worker' in window) run();
+else { text('progress-label', 'This browser needs WebAssembly and Web Workers to render.'); text('render-state', 'SCENE PREVIEW'); }
