diff --git a/src/components/AccountSettings.tsx b/src/components/AccountSettings.tsx
new file mode 100644
index 0000000..3e0d565
--- /dev/null
+++ b/src/components/AccountSettings.tsx
@@ -0,0 +1,84 @@
+import { useEffect, useState } from 'react';
+import { startRegistration } from '@simplewebauthn/browser';
+import { KeyIcon, PencilSquareIcon, TrashIcon, ShieldCheckIcon, ArrowRightIcon } from '@heroicons/react/24/outline';
+import { syncPasskeys, type AccountSnapshot } from '../lib/passkey-sync';
+
+const base = import.meta.env.BASE_URL;
+async function request(path = '', method = 'GET', body?: unknown) {
+  const response = await fetch(`${base}api/account${path}`, { method, headers: body ? { 'Content-Type': 'application/json' } : {}, body: body ? JSON.stringify(body) : undefined });
+  const data = await response.json();
+  if (!response.ok) throw new Error(response.status === 401 ? 'Your session has expired. Please sign in again.' : data.error || 'Unable to save changes. Please try again.');
+  return data;
+}
+export default function AccountSettings() {
+  const [data, setData] = useState<AccountSnapshot | null>(null);
+  const [loading, setLoading] = useState(true);
+  const [busy, setBusy] = useState(false);
+  const [error, setError] = useState('');
+  const [message, setMessage] = useState('');
+  const [sync, setSync] = useState('');
+  const [displayName, setDisplayName] = useState('');
+  const [editing, setEditing] = useState<string | null>(null);
+  const [keyName, setKeyName] = useState('');
+  const [removing, setRemoving] = useState<string | null>(null);
+
+  async function load() {
+    setLoading(true); setError('');
+    try {
+      const next: AccountSnapshot = await request();
+      setData(next); setDisplayName(next.user.displayName);
+      setSync(await syncPasskeys(next, true));
+    } catch (e) { setError((e as Error).message); }
+    finally { setLoading(false); }
+  }
+  useEffect(() => { void load(); }, []);
+
+  async function change(path: string, method: string, body: unknown, success: string, details = false) {
+    setBusy(true); setError(''); setMessage('');
+    try {
+      const next: AccountSnapshot = await request(path, method, body);
+      setData(next); setDisplayName(next.user.displayName); setEditing(null); setRemoving(null);
+      setMessage(success);
+      setSync(await syncPasskeys(next, details));
+    } catch (e) { setError((e as Error).message); }
+    finally { setBusy(false); }
+  }
+  async function add() {
+    setBusy(true); setError(''); setMessage('');
+    try {
+      const optionsJSON = await request('/passkeys', 'POST', { action: 'options' });
+      const response = await startRegistration({ optionsJSON });
+      const next = await request('/passkeys', 'POST', { action: 'verify', response });
+      setData(next); setMessage('Passkey added. You can now use it to sign in.');
+      setSync(await syncPasskeys(next, true));
+    } catch (e) { setError((e as Error).name === 'NotAllowedError' ? 'Passkey setup was canceled or timed out. You can try again.' : (e as Error).message); }
+    finally { setBusy(false); }
+  }
+  if (loading) return <div className="settings-loading" role="status">Loading your account settings…</div>;
+  if (!data) return <div className="settings-gate"><ShieldCheckIcon /><h2>Make yourself at home.</h2><p>Sign in to manage your account and keep your passkeys up to date.</p>{error && <p role="alert">{error}</p>}<a className="settings-primary" href={`${base}signin`}>Sign in to your account <ArrowRightIcon /></a><button className="settings-text" onClick={load}>Try again</button></div>;
+
+  return <div className="settings-panels" aria-busy={busy}>
+    <div className="settings-account"><div><span className="settings-eyebrow">SIGNED IN AS</span><p>{data.user.username}</p></div><button className="settings-text" disabled={busy} onClick={async () => { setBusy(true); try { await request('', 'DELETE'); window.location.assign(`${base}signin`); } catch (e) { setError((e as Error).message); setBusy(false); } }}>Sign out</button></div>
+    {error && <div className="settings-alert error" role="alert">{error} <a href={`${base}signin`}>Sign in</a></div>}
+    {message && <div className="settings-alert success" role="status">{message}</div>}
+    <section className="settings-section" aria-labelledby="profile-title">
+      <span className="settings-eyebrow">YOUR PROFILE</span><h2 id="profile-title">A name to go by.</h2><p>Your display name is shared with your passkey provider to help you recognize your account.</p>
+      <form className="settings-profile-form" onSubmit={e => { e.preventDefault(); void change('', 'PATCH', { displayName: displayName.trim() }, 'Display name updated.', true); }}>
+        <div><label htmlFor="display-name">Display name</label><input id="display-name" autoComplete="nickname" value={displayName} onChange={e => setDisplayName(e.target.value)} required maxLength={64} disabled={busy} /></div>
+        <button className="settings-secondary" disabled={busy || !displayName.trim() || displayName.trim() === data.user.displayName}>Save changes</button>
+      </form>
+    </section>
+    <section className="settings-section" aria-labelledby="passkeys-title">
+      <div className="settings-section-top"><div><span className="settings-eyebrow">SIGN-IN & SECURITY</span><h2 id="passkeys-title">Your passkeys<span className="settings-count">{data.passkeys.length}</span></h2></div><button className="settings-primary" onClick={add} disabled={busy}><span aria-hidden="true">+</span> Add a passkey</button></div>
+      <p>A simpler, safer way to sign in. Manage the passkeys connected to your account.</p>
+      {data.passkeys.length === 0 ? <div className="settings-empty"><KeyIcon /><h3>No passkeys yet</h3><p>Add your first passkey to sign in with your fingerprint, face, or device screen lock.</p></div> : <ul className="settings-key-list">{data.passkeys.map(key => <li key={key.id}>
+        <div className="settings-key-row"><div className="settings-key-icon"><KeyIcon /></div><div className="settings-key-info">{editing === key.id ? <form className="settings-rename" onSubmit={e => { e.preventDefault(); void change('/passkeys', 'PATCH', { id: key.id, name: keyName.trim() }, 'Passkey name updated. This label is saved in your account.'); }}><label className="sr-only" htmlFor={`key-${key.id}`}>Passkey name</label><input id={`key-${key.id}`} autoFocus value={keyName} onChange={e => setKeyName(e.target.value)} maxLength={64} required disabled={busy} /><button className="settings-text" disabled={busy || !keyName.trim()}>Save</button><button type="button" className="settings-text" disabled={busy} onClick={() => setEditing(null)}>Cancel</button></form> : <h3>{key.name}</h3>}<p>Added {new Intl.DateTimeFormat('en', { month: 'short', day: 'numeric', year: 'numeric', timeZone: 'UTC' }).format(new Date(key.createdAt))}</p></div>
+        <div className="settings-key-actions"><button aria-label={`Rename ${key.name}`} title="Rename passkey" disabled={busy || editing !== null} onClick={() => { setEditing(key.id); setKeyName(key.name); setRemoving(null); }}><PencilSquareIcon /></button><button aria-label={`Remove ${key.name}`} title="Remove passkey" disabled={busy} onClick={() => { setRemoving(key.id); setEditing(null); }}><TrashIcon /></button></div></div>
+        {removing === key.id && <div className="settings-confirm" role="group" aria-label={`Confirm removal of ${key.name}`}><h4>Remove “{key.name}”?</h4><p>You won’t be able to sign in with this passkey. You can still use your password{data.passkeys.length > 1 ? ' or another passkey' : ''}.</p><div><button className="settings-danger" disabled={busy} onClick={() => change('/passkeys', 'DELETE', { id: key.id }, 'Passkey removed from your account.')}>{busy ? 'Removing…' : 'Remove passkey'}</button><button className="settings-text" disabled={busy} onClick={() => setRemoving(null)}>Keep passkey</button></div></div>}
+      </li>)}</ul>}
+      <div className="settings-security-note"><ShieldCheckIcon /><p>Your biometric information stays on your device. Only you can use your passkeys.</p></div>
+      {sync && <div className="settings-sync" role="status"><p>{sync}</p><button className="settings-text" disabled={busy} onClick={async () => { setBusy(true); try { const next = await request(); setData(next); setSync(await syncPasskeys(next, true)); } catch (e) { setError((e as Error).message); } finally { setBusy(false); } }}>Retry sync</button></div>}
+    </section>
+    <p className="settings-footnote">Passkey labels help you identify devices here. Your display name is the name used by your password manager.</p>
+  </div>;
+}
