+/* Account and authentication */
+:root { --account-ink: #202923; --account-muted: #778079; --account-green: #285b45; --account-border: #e4e8e2; }
+.settings-shell, .auth-layout { color: var(--account-ink); font-family: Arial, Helvetica, sans-serif; font-size: 14px; line-height: 1.6; }
+.settings-shell { padding: 25px 42px 0; background: #fff; }
+.settings-breadcrumb { display: flex; align-items: center; gap: 10px; font-size: 11px; color: #8a908b; margin-bottom: 34px; }
+.settings-breadcrumb svg { width: 11px; }
+.settings-breadcrumb span { color: #444e46; }
+.settings-layout { display: grid; grid-template-columns: 213px minmax(0,1fr); gap: 42px; }
+.eyebrow { display: block; font-size: 9px; letter-spacing: 1.65px; font-weight: 700; color: #858c83; }
+.settings-sidebar { border-right: 1px solid var(--account-border); padding-right: 24px; }
+.settings-sidebar h1 { font-family: Georgia, serif; font-size: 31px; letter-spacing: -1.3px; line-height: 1.2; margin: 12px 0 7px; }
+.settings-sidebar h1 span { color: #62927a; }
+.settings-sidebar > p { color: #828881; font-size: 11px; }
+.settings-sidebar nav { display: flex; flex-direction: column; gap: 7px; margin: 30px -10px 0; }
+.sidebar-link { padding: 11px 10px; border-radius: 5px; display: flex; align-items: center; gap: 10px; font-size: 11px; font-weight: 500; color: #687169; }
+.sidebar-link > svg { width: 17px; height: 17px; }
+.sidebar-link > svg:last-child:not(:first-child) { width: 12px; margin-left: auto; }
+.sidebar-link.active { background: #edf3ed; color: #285b45; font-weight: 700; }
+.sidebar-link:hover { background: #f3f5f1; }
+.sidebar-footer { border-top: 1px solid var(--account-border); margin-top: 38px; padding-top: 24px; }
+.sidebar-footer p { font-family: Georgia,serif; font-size: 18px; line-height: 1.45; color: #8b9287; }
+.sidebar-footer a { display: flex; gap: 7px; align-items: center; font-size: 10px; margin-top: 14px; }
+.sidebar-footer svg { width: 12px; }
