@@ -0,0 +1,11 @@
+import './audit-privacy.mjs';
+import { cp, mkdir, rm } from 'node:fs/promises';
+
+const output = new URL('../dist/', import.meta.url);
+await rm(output, { recursive: true, force: true });
+await mkdir(output);
+// Ship only reviewed public files, never tooling, documentation, or repository data.
+for (const file of ['index.html', 'privacy-policy.html', 'assets', '_headers']) {
+  await cp(new URL(`../${file}`, import.meta.url), new URL(file, output), { recursive: true });
+}
+console.log('Static build written to dist/; no server started.');

