+const { test } = require('node:test');
+const assert = require('node:assert/strict');
+const { Readable } = require('node:stream');
+const { readFile } = require('node:fs/promises');
+// This module exports a handler only; it never imports server.js or opens sockets.
+const { createHandler } = require('../app');
+
+const origin = 'https://coffee.example';
+async function request(handler, { url = '/', method = 'GET', headers = {}, body = '' } = {}) {
+  const req = Readable.from([Buffer.from(body)]);
+  Object.assign(req, { url, method, headers });
+  const response = { headers: {}, setHeader(name, value) { this.headers[name] = value; },
+    writeHead(status, headers) { this.status = status; Object.assign(this.headers, headers); },
+    end(body) { this.body = body?.toString() || ''; } };
+  await handler(req, response);
+  return response;
+}
+
+test('markup and CSS remain compatible with a no-script, no-inline policy', async () => {
+  const html = await readFile('index.html', 'utf8');
+  assert.doesNotMatch(html, /<script\b|<style\b|\sstyle\s*=|\son\w+\s*=|javascript:/i);
+  assert.match(html, /<link rel="stylesheet" href="\/styles.css">/);
+  assert.match(html, /<form method="post" action="\/logout">/);
+  const res = await request(createHandler({ publicOrigin: origin }));
+  assert.equal(res.status, 200);
+  const csp = res.headers['Content-Security-Policy'];
+  for (const directive of ["default-src 'none'", "script-src 'none'", "style-src 'self'",
+    "trusted-types 'none'", "require-trusted-types-for 'script'", "frame-ancestors 'none'",
+    'img-src https://images.unsplash.com', 'report-uri /security-reports', 'report-to security']) {
+    assert.ok(csp.includes(directive), directive);
+  }
+  assert.equal(res.headers['Reporting-Endpoints'], 'security="https://coffee.example/security-reports"');
+  assert.equal(res.headers['Strict-Transport-Security'], 'max-age=300');
+  assert.equal(res.headers['X-Content-Type-Options'], 'nosniff');
+  assert.equal(res.headers['X-Frame-Options'], 'DENY');
+  assert.equal(res.headers['Cross-Origin-Opener-Policy'], 'same-origin-allow-popups');
+  assert.equal(res.headers['Cross-Origin-Resource-Policy'], 'same-origin');
+  assert.equal(res.headers['Referrer-Policy'], 'strict-origin-when-cross-origin');
+  assert.match(res.headers['Permissions-Policy'], /camera=\(\)/);
+});
+
+test('stylesheet and HEAD use correct MIME and empty HEAD body', async () => {
+  const handler = createHandler();
+  const css = await request(handler, { url: '/styles.css' });
+  assert.equal(css.headers['Content-Type'], 'text/css; charset=utf-8');
+  assert.match(css.body, /\.hero/);
+  const head = await request(handler, { method: 'HEAD' });
+  assert.equal(head.status, 200);
+  assert.equal(head.body, '');
+  assert.equal(head.headers['Strict-Transport-Security'], undefined);
+});
+
+test('report-only mode retains baseline protections; invalid config fails closed', async () => {
+  const res = await request(createHandler({ cspMode: 'report-only' }));
+  assert.match(res.headers['Content-Security-Policy-Report-Only'], /script-src 'none'/);
+  assert.match(res.headers['Content-Security-Policy'], /frame-ancestors 'none'/);
+  assert.doesNotMatch(res.headers['Content-Security-Policy'], /script-src/);
+  assert.throws(() => createHandler({ cspMode: 'off' }));
+  assert.throws(() => createHandler({ publicOrigin: 'https://coffee.example/path' }));
+});
+
+test('logout rejects GET, cross-origin and missing Origin, clearing data only on valid POST', async () => {
+  const handler = createHandler({ publicOrigin: origin });
+  for (const url of ['/logout', '/logout/']) {
+    const get = await request(handler, { url });
+    assert.equal(get.status, 405);
+    assert.equal(get.headers['Clear-Site-Data'], undefined);
+    for (const headers of [{}, { origin: 'https://evil.example' },
+      { origin, 'sec-fetch-site': 'same-site' }]) {
+      assert.equal((await request(handler, { url, method: 'POST', headers })).status, 403);
+    }
+    const post = await request(handler, { url, method: 'POST', headers: { origin, 'sec-fetch-site': 'same-origin' } });
+    assert.equal(post.status, 200);
+    assert.equal(post.headers['Clear-Site-Data'], '"cookies", "storage", "cache"');
+  }
+});
+
+test('fetch metadata blocks cross-site resources while preserving incoming navigations', async () => {
+  const handler = createHandler();
+  const blocked = await request(handler, { headers: { 'sec-fetch-site': 'cross-site' } });
+  assert.equal(blocked.status, 403);
+  assert.equal(blocked.headers['X-Content-Type-Options'], 'nosniff');
+  assert.match(blocked.headers.Vary, /Sec-Fetch-Site/);
+  const nav = await request(handler, { headers: { 'sec-fetch-site': 'cross-site',
+    'sec-fetch-mode': 'navigate', 'sec-fetch-dest': 'document' } });
+  assert.equal(nav.status, 200);
+});
+
+test('both report formats log only allowlisted fields, never supplied secrets', async () => {
+  const reports = [];
+  const handler = createHandler({ onReport: (report) => reports.push(report) });
+  const body = { 'effective-directive': 'script-src-elem', disposition: 'report',
+    'document-uri': 'https://coffee.example/?secret=token', 'script-sample': 'private' };
+  assert.equal((await request(handler, { url: '/security-reports', method: 'POST',
+    headers: { 'content-type': 'application/csp-report' }, body: JSON.stringify({ 'csp-report': body }) })).status, 204);
+  assert.equal((await request(handler, { url: '/security-reports', method: 'POST',
+    headers: { 'content-type': 'application/reports+json' }, body: JSON.stringify([
+      { type: 'csp-violation', body: { effectiveDirective: 'trusted-types', disposition: 'enforce', sourceFile: 'secret' } },
+      { type: 'deprecation', body: { effectiveDirective: 'script-src' } }, null,
+    ]) })).status, 204);
+  assert.deepEqual(reports, [{ directive: 'script-src-elem', disposition: 'report' },
+    { directive: 'trusted-types', disposition: 'enforce' }]);
+});
+
+test('report endpoint bounds body size, batches, content type and malformed JSON', async () => {
+  const handler = createHandler();
+  const base = { url: '/security-reports', method: 'POST', headers: { 'content-type': 'application/csp-report' } };
+  assert.equal((await request(handler, { ...base, body: 'x'.repeat(16385) })).status, 413);
+  assert.equal((await request(handler, { ...base, body: JSON.stringify(Array(21).fill({})) })).status, 413);
+  assert.equal((await request(handler, { ...base, body: '{' })).status, 400);
+  assert.equal((await request(handler, { ...base, headers: { 'content-type': 'text/plain' } })).status, 415);
+  assert.equal((await request(handler, { url: '/security-reports' })).status, 405);
+});
+
+test('reports are rate limited and untrusted Host does not affect reporting URLs', async () => {
+  const handler = createHandler({ publicOrigin: origin });
+  const res = await request(handler, { headers: { host: 'evil.example', 'x-forwarded-proto': 'http' } });
+  assert.equal(res.headers['Reporting-Endpoints'], 'security="https://coffee.example/security-reports"');
+  for (let i = 0; i < 100; i++) {
+    assert.equal((await request(handler, { url: '/security-reports', method: 'POST',
+      headers: { 'content-type': 'application/reports+json' }, body: '[]' })).status, 204);
+  }
+  assert.equal((await request(handler, { url: '/security-reports', method: 'POST',
+    headers: { 'content-type': 'application/reports+json' }, body: '[]' })).status, 429);
+});

